CREATE TYPE "regional_competitor_kind" AS ENUM ('direct', 'indirect', 'substitute', 'aspirational', 'emerging');
CREATE TYPE "regional_monitor_run_status" AS ENUM ('queued', 'running', 'completed', 'failed');
CREATE TYPE "regional_alert_status" AS ENUM ('open', 'acknowledged');
CREATE TABLE "regional_profiles" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE cascade, "campaign_id" uuid NOT NULL REFERENCES "campaigns"("id") ON DELETE cascade, "region" text NOT NULL, "locale" text DEFAULT 'pt-BR' NOT NULL, "config" jsonb DEFAULT '{}'::jsonb NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "regional_profiles_workspace_campaign_uidx" ON "regional_profiles" ("workspace_id","campaign_id");
CREATE TABLE "regional_competitors" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE cascade, "campaign_id" uuid NOT NULL REFERENCES "campaigns"("id") ON DELETE cascade, "name" text NOT NULL, "kind" "regional_competitor_kind" NOT NULL, "website_url" text, "normalized_website_url" text, "notes" text, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "regional_competitors_workspace_campaign_url_uidx" ON "regional_competitors" ("workspace_id","campaign_id","normalized_website_url");
CREATE INDEX "regional_competitors_workspace_campaign_idx" ON "regional_competitors" ("workspace_id","campaign_id");
CREATE TABLE "regional_public_sources" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE cascade, "campaign_id" uuid NOT NULL REFERENCES "campaigns"("id") ON DELETE cascade, "competitor_id" uuid REFERENCES "regional_competitors"("id") ON DELETE cascade, "url" text NOT NULL, "normalized_url" text NOT NULL, "title" text, "source_type" text DEFAULT 'public_web' NOT NULL, "verified_at" timestamp with time zone NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "regional_sources_workspace_campaign_url_uidx" ON "regional_public_sources" ("workspace_id","campaign_id","normalized_url");
CREATE INDEX "regional_sources_workspace_campaign_idx" ON "regional_public_sources" ("workspace_id","campaign_id");
CREATE TABLE "regional_evidence" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE cascade, "campaign_id" uuid NOT NULL REFERENCES "campaigns"("id") ON DELETE cascade, "source_id" uuid NOT NULL REFERENCES "regional_public_sources"("id") ON DELETE cascade, "fingerprint" text NOT NULL, "claim" text NOT NULL, "payload" jsonb DEFAULT '{}'::jsonb NOT NULL, "observed_at" timestamp with time zone NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "regional_evidence_workspace_fingerprint_uidx" ON "regional_evidence" ("workspace_id","fingerprint");
CREATE INDEX "regional_evidence_workspace_campaign_idx" ON "regional_evidence" ("workspace_id","campaign_id");
CREATE TABLE "regional_observations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE cascade, "campaign_id" uuid NOT NULL REFERENCES "campaigns"("id") ON DELETE cascade, "competitor_id" uuid NOT NULL REFERENCES "regional_competitors"("id") ON DELETE cascade, "evidence_id" uuid NOT NULL REFERENCES "regional_evidence"("id") ON DELETE cascade, "fingerprint" text NOT NULL, "facts" jsonb DEFAULT '{}'::jsonb NOT NULL, "observed_at" timestamp with time zone NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "regional_observations_workspace_fingerprint_uidx" ON "regional_observations" ("workspace_id","fingerprint");
CREATE INDEX "regional_observations_competitor_time_idx" ON "regional_observations" ("workspace_id","competitor_id","observed_at");
CREATE TABLE "regional_change_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE cascade, "campaign_id" uuid NOT NULL REFERENCES "campaigns"("id") ON DELETE cascade, "competitor_id" uuid NOT NULL REFERENCES "regional_competitors"("id") ON DELETE cascade, "observation_id" uuid NOT NULL REFERENCES "regional_observations"("id") ON DELETE cascade, "previous_observation_id" uuid REFERENCES "regional_observations"("id") ON DELETE set null, "changes" jsonb NOT NULL, "material" text DEFAULT 'true' NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, CONSTRAINT "regional_change_events_material_check" CHECK ("regional_change_events"."material" in ('true', 'false')));
CREATE UNIQUE INDEX "regional_change_events_observation_uidx" ON "regional_change_events" ("observation_id");
CREATE INDEX "regional_change_events_workspace_campaign_idx" ON "regional_change_events" ("workspace_id","campaign_id","created_at");
CREATE TABLE "regional_monitor_runs" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE cascade, "campaign_id" uuid NOT NULL REFERENCES "campaigns"("id") ON DELETE cascade, "idempotency_key" text NOT NULL, "status" "regional_monitor_run_status" DEFAULT 'queued' NOT NULL, "started_at" timestamp with time zone, "completed_at" timestamp with time zone, "error" text, "summary" jsonb DEFAULT '{}'::jsonb NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "regional_monitor_runs_workspace_campaign_key_uidx" ON "regional_monitor_runs" ("workspace_id","campaign_id","idempotency_key");
CREATE INDEX "regional_monitor_runs_workspace_campaign_idx" ON "regional_monitor_runs" ("workspace_id","campaign_id","created_at");
CREATE TABLE "regional_alerts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE cascade, "campaign_id" uuid NOT NULL REFERENCES "campaigns"("id") ON DELETE cascade, "change_event_id" uuid NOT NULL REFERENCES "regional_change_events"("id") ON DELETE cascade, "status" "regional_alert_status" DEFAULT 'open' NOT NULL, "acknowledged_at" timestamp with time zone, "acknowledged_by_user_id" uuid, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "regional_alerts_change_event_uidx" ON "regional_alerts" ("change_event_id");
CREATE INDEX "regional_alerts_workspace_campaign_status_idx" ON "regional_alerts" ("workspace_id","campaign_id","status");